export type ConnectionPayload = {
	status: string,
	needs_pairing_check: boolean,
	/**
	 *  Configured relays with a live socket right now — Settings' per-relay
	 *  status dot. Not a subscription/publish-readiness signal, just "the
	 *  socket is up." A relay dropping without the overall `status`
	 *  changing does not push a fresh value; it's refreshed by whatever
	 *  next causes a real reconnect-class transition or a manual re-query.
	 */
	connected_relays: string[],
};

/**
 *  The closed, semantic event set (plan §2.3). Serde shape: externally
 *  tagged, camelCase (same convention as [`crate::intent::Intent`]) — e.g.
 *  `{"stateChanged": {"slice": "machines"}}`.
 */
export type CoreEvent = 
/**  The named view slice changed — re-read it. */
({ stateChanged: {
	slice: SliceId,
} }) & { actionFailed?: never; outboxSettled?: never; pairingSettled?: never; transcriptAppended?: never } | 
/**
 *  An outbox item reached a terminal state (`delivered` = bridge ack'd, not
 *  just published).
 */
({ outboxSettled: {
	id: string,
	delivered: boolean,
} }) & { actionFailed?: never; pairingSettled?: never; stateChanged?: never; transcriptAppended?: never } | 
/**  The pair flow ended: `paired` true on success, false on nack / timeout. */
({ pairingSettled: {
	paired: boolean,
} }) & { actionFailed?: never; outboxSettled?: never; stateChanged?: never; transcriptAppended?: never } | 
/**  A user-visible action did not land. Semantic — the UI writes the copy. */
({ actionFailed: {
	kind: ActionFailed,
} }) & { outboxSettled?: never; pairingSettled?: never; stateChanged?: never; transcriptAppended?: never } | 
/**
 *  New rows landed for this session (a live `Output`, or a `SyncChunk`
 *  filling a gap) — a dedicated, per-session event rather than a generic
 *  `StateChanged { slice: Transcript }`, since a blanket slice notify
 *  cannot tell a consumer WHICH session to re-fetch and transcripts are
 *  per-session by nature.
 */
({ transcriptAppended: {
	machine: string,
	sessionId: string,
} }) & { actionFailed?: never; outboxSettled?: never; pairingSettled?: never; stateChanged?: never };

